insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '권징의 목적 중 범죄한 자를 위한 것은?', '["범죄자를 공개적으로 비난하는 것", "범죄자에게 육체적 형벌을 주는 것", "범죄한 자의 신령적 유익을 도모하는 것", "범죄자를 영원히 추방하는 것"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '권징의 목적이 아닌 것은?', '["덕을 세우는 것", "교회의 재정 증식", "그리스도의 권위와 존영을 견고하게 하는 것", "악행을 제거하는 것"]'::jsonb, 1);
