insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''이 밖에는 소송하는 자가 원고가 된다''는 규정은 무엇을 나타냅니까?', '["치리회가 아닌 경우, 고소를 제기하는 개인이 원고가 된다.", "모든 소송은 익명으로 진행된다.", "소송은 항상 치리회에 의해서만 시작된다.", "치리회만 원고가 될 수 있다."]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '치리회가 원고가 되어 기소하는 경우, 기소 위원의 역할은?', '["변호인의 역할을 한다.", "치리회의 위임을 받아 원고로서 기소 절차를 진행한다.", "재판에 참여하지 않는다.", "개인적으로 판결을 내린다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판건 성립의 세 가지 요인 중 첫 번째는?', '["피고의 자백", "증인의 증언", "원고의 고소", "치리회의 결정"]'::jsonb, 2);
