insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판건 성립의 세 가지 요인 중 세 번째는? (마 18:15-17 근거)', '["증거 부족", "권면해도 불응하는 악심자", "합의에 이르는 경우", "재판 회피"]'::jsonb, 2);
