insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판 안건이 되지 못하는 경우 중 하나는?', '["권징조례로 금지할 일인 경우", "교회의 명예를 실추시키는 행위인 경우", "성경에 의하여 제정한 교회 규칙과 관례에 위반되지 않는 경우", "성경에 의하여 제정한 교회 규칙과 관례에 위반되는 경우"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판 안건이 되지 못하는 또 다른 경우는?', '["덕을 세움에 방해되는 경우", "교훈과 심술과 행위가 성경에 위반되는 경우", "권징조례로 금지할 일이 아니면", "다른 사람으로 범죄하게 한 경우"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판 안건이 되지 못하는 경우를 명시하는 주된 이유는?', '["모든 문제를 화해로 해결하기 위함", "재판을 최소화하기 위함", "교회의 법적 판단 기준을 명확히 하여 불필요한 소송을 방지하고 질서를 유지하기 위함", "교회 직분자들의 부담을 줄이기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '교회 규칙과 관례에 위반되지 않는 사안이 재판 안건이 될 수 없다는 것은 무엇을 강조합니까?', '["교회의 자율성", "교회의 법치주의", "교회의 법적 근거", "교회의 관습 준수"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '치리회가 재판회를 회집하면 회장이 먼저 그 이유를 공포하고 정중히 처리하기를 선언한 후 무엇을 낭독합니까?', '["회의록", "고소장과 죄증 설명서", "재판국의 국원 명단", "판결문"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판 회집 시 회장이 ''그 이유를 공포하고 정중히 처리하기를 선언''하는 주된 이유는?', '["교인들에게 재판의 필요성을 설명하기 위함", "재판의 시작을 알리기 위함", "재판장의 권위를 내세우기 위함", "재판의 엄중함과 공정성을 명확히 하기 위함"]'::jsonb, 3);
