insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''이단을 주장하는 것''이 목사를 면직할 만한 죄로 규정되는 주된 이유는?', '["교인들의 혼란을 야기하기 때문", "사회적으로 비난받을 수 있기 때문", "개인적인 명예를 손상시키기 때문", "교회의 근본 진리를 훼손하여 교회의 정체성을 위협하기 때문"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''불법으로 교회를 분립하는 행동''이 목사를 면직할 만한 죄로 규정되는 이유는?', '["교회의 재정적 손실을 가져오기 때문", "목사의 개인적인 이익을 추구하기 때문", "교인들의 수가 줄어들기 때문", "교회의 일치를 깨뜨리고 분열을 조장하여 교회의 본질을 훼손하기 때문"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '담임 목사가 정직을 당하여 상소할 경우, 즉시 담임을 해제할 수 있습니까?', '["있다", "없다", "노회의 결정에 따라 다르다", "교인들의 동의가 있으면 가능하다"]'::jsonb, 1);
