insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '이러한 규정은 교회의 재판 절차가 무엇을 중요하게 여김을 보여줍니까?', '["신속성", "상소권과 최종 판결의 확정성", "일사부재리 원칙", "하회의 권한"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '즉결 처단을 할 수 있는 경우 중 하나는?', '["교인이 개인적인 불만을 제기할 때", "목회자가 개인적인 의견을 피력할 때", "교인들이 재정 지원을 요청할 때", "치리회 석상에서 범죄한 사건"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '즉결 처단을 할 수 있는 또 다른 경우는?', '["범죄를 저지른 자가 도망쳤을 때", "타처에서 범죄한 것을 본인이 자복했을 경우", "범죄가 경미할 때", "증거가 불충분할 때"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '즉결 처단이 가능한 주된 이유는?', '["교회의 명예를 보호하기 위함", "교인들에게 강한 경고를 주기 위함", "범죄 사실이 명백하거나 자백을 통해 명확해졌기 때문에 재판 절차 없이 즉시 처결할 수 있기 때문", "재판 과정을 생략하여 신속하게 처리하기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '즉결 처단 시 치리회가 먼저 해야 할 일은?', '["바로 처벌한다.", "그 사실을 청취한 후 처결한다.", "교인들에게 의견을 묻는다.", "변호인을 선임한다."]'::jsonb, 1);
