insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판국의 성수 요건 중 또 다른 중요한 사항은?', '["과반수 이상이 평신도여야 한다.", "모든 국원이 장로여야 한다.", "반수 이상이 목사가 되어야 한다.", "특정 지역 출신이어야 한다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판국 성수 규정의 주된 목적은?', '["재판국 운영 비용을 절감하기 위함", "재판의 합법성과 공정성을 보장하여 그 결정의 효력을 강화하기 위함", "국원들의 책임감을 높이기 위함", "재판 진행을 지연시키기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '재판국 성수가 미달될 경우 발생할 수 있는 문제는?', '["재판이 더 신속하게 진행된다.", "재판 결과의 법적 효력이 인정되지 않을 수 있다.", "국원들의 부담이 증가한다.", "교회의 재정 문제가 발생한다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '상설 재판국은 합법적으로 해마다 국원 몇 분의 몇을 개선하는 재판국입니까?', '["3 분의 1", "전원", "2 분의 1", "4 분의 1"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '상설 재판국은 사건의 유무에 불구하고 항상 조직해 두는 재판국이라는 의미인데, 이는 무엇을 강조합니까?', '["특정 사건만을 다룬다.", "재판의 임시적인 성격", "재판의 신속한 종결", "재판의 지속적인 운영과 전문성 유지"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '상설 재판국을 두는 목적은?', '["재판의 수를 늘리기 위함", "교회 내 재판 업무의 지속성과 전문성을 확보하고, 언제든지 발생할 수 있는 재판에 효율적으로 대응하기 위함", "재판국원들의 임기를 보장하기 위함", "재판 비용을 절감하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '총회 상설 재판국은 목사 몇 인과 장로 몇 인을 국원으로 선정합니까?', '["목사 5 인, 장로 5 인", "목사 6 인, 장로 5 인", "목사 8 인, 장로 7 인", "목사 10 인, 장로 5 인"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '총회 재판국원의 성수는 몇 인으로 정합니까?', '["7 인", "9 인", "11 인", "15 인"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '총회 재판국원 성수 중 목사는 몇 인임을 요합니까?', '["4 인", "5 인", "6 인", "7 인"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '총회 상설 재판국의 구성에서 목사 인원이 장로 인원보다 많은 주된 이유는?', '["교리적, 신학적 전문성을 요구하는 최상급 재판의 특성 때문", "총회 운영을 효율적으로 하기 위함", "장로의 책임감을 줄이기 위함", "목사의 권한을 강화하기 위함"]'::jsonb, 0);
