insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 장로가 회개하면 당회의 결의로 무엇을 해벌하고 성찬에 참여케 합니까?', '["견책", "정직", "출교", "면직"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 당한 장로가 다시 임직을 받기 위해 필요한 절차는?', '["자동으로 복직된다.", "교회가 다시 투표하여 장립 예식을 행한 후에 임직이 가능하다.", "1 년 동안 봉사하면 자동 임직된다.", "노회의 지시만 받으면 된다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 당한 목사가 복직할 수 있는 곳은?', '["총회", "노회", "면직한 치리회 앞에서 복직하거나, 그 회의 결의대로 위탁받은 치리회", "당회"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 당한 목사의 복직은 누가 최종적으로 허락합니까?', '["총회장", "해당 지교회 당회", "면직 처분을 내렸던 치리회", "교인 전체"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 당한 목사가 복직하기 위해 가장 먼저 필요한 것은?', '["새로운 신학교 졸업", "교인들의 동의", "재정적 보상", "진정한 회개"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '면직 당한 목사의 복직 절차가 엄격한 주된 이유는?', '["목사의 편의를 위함", "목사직의 중요성과 면직 처분의 중대성을 반영하여 신중한 절차를 거치기 위함", "목회자의 명예를 훼손하기 위함", "다른 교회로 가지 못하게 하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '당회 재판 없이 즉시 처결할 수 있는 경우 중 하나는?', '["교인들이 봉사 활동을 요청할 때", "목회자가 성경 공부를 지도할 때", "교인이 개인적인 고민을 토로할 때", "치리회 석상에서 범죄한 사건"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '당회 재판 없이 즉시 처결할 수 있는 또 다른 경우는?', '["증거가 불충분할 때", "범죄가 경미한 경우", "타처에서 범죄한 것을 본인이 자복했을 때", "범죄 사실이 복잡할 때"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '즉결 처단 제도가 필요한 주된 이유는?', '["재정적인 부담을 줄이기 위함", "명백한 범죄에 대해 신속하게 교회의 질서를 회복하고 죄악에 대한 단호한 입장을 표명하기 위함", "모든 재판 과정을 생략하기 위함", "교회의 명예를 보호하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '위탁 판결을 하는 주된 이유는 무엇입니까?', '["재판을 피하기 위함", "본 회의에서 결정하기 어려운 재판 사건에 대하여 지도를 구하는 것", "모든 재판을 상회에 맡기기 위함", "하회의 책임을 회피하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '위탁 판결은 하회의 어떤 면을 보완하기 위한 제도입니까?', '["권한 부족", "구성원 부족", "책임감 부족", "전문성 또는 판단의 어려움"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '상소는 하회에서 판결한 어떤 사건에 대하여 서면으로 상회에 제출하는 것입니까?', '["재판 사건", "인사 문제", "행정 사건", "재정 문제"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '상소는 하회의 판결에 대해 무엇을 구하는 절차입니까?', '["보고", "재심 또는 변경", "승인", "감사"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '상소는 누구에게 제출합니까?', '["하회 재판국", "총회장", "개인 변호인", "상회"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '상소 제도가 필요한 주된 이유는?', '["재판 진행을 지연시키기 위함", "하회 재판의 오류나 불공정을 시정하고 재판 당사자의 권리를 보호하기 위함", "하회의 권한을 약화시키기 위함", "재판의 확정성을 강조하기 위함"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '상소할 수 있는 사유 중 ''하회가 재판을 불법하게 하는 때''는 무엇을 의미합니까?', '["재판 결과가 마음에 들지 않을 때", "재판 절차나 법규를 위반하여 재판을 진행했을 때", "재판장이 교인들과 사이가 좋지 않을 때", "재판이 너무 오래 걸릴 때"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''하회가 상소하는 것을 불허하는 때''는 상소 사유가 됩니까?', '["아니다", "그렇다", "상회의 동의가 있어야 한다", "재판국의 결정에 따른다"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '상소 사유 중 ''불합당하게 증거를 채용하는 때''는 어떤 경우입니까?', '["모든 증거를 채용하지 않는 경우", "증거가 너무 많을 때", "증거를 너무 늦게 제출할 때", "증거 능력이 없는 것을 채용하거나, 증거 조작이 의심될 때"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''판결 오착이나 불공평이 있는 때''가 상소 사유가 되는 주된 이유는?', '["불만을 표출할 기회를 제공하기 위함", "재판의 권위를 훼손하기 위함", "재판의 완벽성을 추구하기 위함", "하회의 판단 오류로 인해 재판 결과가 진실에 부합하지 않거나 당사자에게 불합리하게 적용되었을 때 이를 시정하기 위함"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '당회 재판에 대하여 노회에 상소하는 것을 무엇이라고 합니까?', '["재심", "공소", "소원", "상고"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '노회 재판에 대하여 총회에 상소하는 것을 무엇이라고 합니까?', '["재심", "상고", "공소", "소원"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '공소와 상고를 구분하는 가장 중요한 기준은?', '["상소하는 당사자", "재판의 결과", "상소하는 하회와 심의하는 상회", "재판의 내용"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '소원이란 무엇을 요구하는 행정 소송입니까?', '["행정 처리의 취소나 변경이나 촉구", "책벌", "직분 임명", "재정 지원"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '소원장을 통해 책벌을 할 수 있습니까?', '["있다", "없다", "경우에 따라 다르다", "노회의 결정에 따른다"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '소원이 ''요구서가 아니라 행정 처리의 취소나 변경이나 촉구를 요구하는 행정 소송''이라는 것은 무엇을 강조합니까?', '["소원이 교인의 의견 표출 수단임을 강조한다.", "소원이 행정적 불합리에 대한 시정 요구임을 강조한다.", "소원이 권징의 수단임을 강조한다.", "소원이 재판 사건임을 강조한다."]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '고소나 상소 등 책벌 요구에 대한 재판국의 최후 결정은 무엇입니까?', '["판결문", "심의서", "결정서", "보고서"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '행정 처결의 촉구, 변경, 취소 등을 요구하는 소원에 대한 최후 결정은 무엇입니까?', '["판결문", "보고서", "심의서", "결정서"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '판결문과 결정서의 가장 큰 차이점은?', '["판결문은 하회에서, 결정서는 상회에서만 발행된다.", "판결문은 공개되고, 결정서는 비공개이다.", "판결문은 책벌 요구에 대한 재판 결과이고, 결정서는 행정 소원에 대한 결과이다.", "판결문은 행정건에, 결정서는 재판건에 사용된다."]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '이 두 문서의 차이를 명확히 하는 이유는?', '["문서의 종류를 늘리기 위함", "책임 소재를 불분명하게 하기 위함", "행정 편의를 위함", "재판과 행정의 성격을 구분하고, 각 결정의 법적 효력과 의미를 명확히 하기 위함"]'::jsonb, 3);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '범죄 발각 후 고소를 제기할 수 있는 일반적인 기간은?', '["6 개월", "1 년", "2 년", "3 년"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '교회에 중대한 영향을 끼칠 만한 사건의 경우, 범죄 발각 후 고소를 제기할 수 있는 기간은?', '["1 년", "2 년", "3 년", "5 년"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '범죄에 대한 고소 제기 기간을 제한하는 주된 이유는?', '["범죄자를 보호하기 위함", "모든 사건을 빨리 종결하기 위함", "시간이 경과함에 따라 증거 확보가 어려워지고, 관계 회복의 기회를 주기 위함", "교회의 부담을 줄이기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''교회에 중대한 영향을 끼칠 만한 사건''에 더 긴 공소시효를 두는 이유는?', '["중대 범죄는 그 파급력이 커서 더 오랜 기간 심의와 처벌의 필요성이 인정되기 때문", "사회 법률을 따르기 위함", "더 많은 증거를 찾기 위함", "중요하지 않은 사건은 빨리 잊기 위함"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '결정에 동의하지 아니함을 밝히는 것은 무엇입니까?', '["상소", "이의", "항의", "소원"]'::jsonb, 1);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '과실 되는 것을 증명함을 밝히는 것은 무엇입니까?', '["항의", "이의", "상소", "소원"]'::jsonb, 0);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''이의''를 제기하는 주된 목적은?', '["회의 진행을 방해하기 위함", "결정의 내용을 바꾸기 위함", "특정 결정에 대한 자신의 비동의를 공식적으로 기록하고, 향후 불복의 기초를 마련하기 위함", "다른 사람들에게 자신의 의견을 강요하기 위함"]'::jsonb, 2);
insert into public.exam_questions (subject, question, options, answer) values ('권징조례', '''항의서''를 제출하는 주된 목적은?', '["단순한 불만을 표출하기 위함", "특정 결정이나 행위의 오류나 위법성을 증명하고 시정을 요구하기 위함", "회의에 참여하지 않기 위함", "개인적인 감정을 표현하기 위함"]'::jsonb, 1);
